CREATE TABLE IF NOT EXISTS scheduler_agents (agent_id TEXT PRIMARY KEY, last_seen_at TIMESTAMPTZ, last_sync_at TIMESTAMPTZ, last_error TEXT NOT NULL DEFAULT '', metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS scheduler_sync_jobs (id BIGSERIAL PRIMARY KEY, agent_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','running','completed','failed')), requested_by BIGINT REFERENCES users(id) ON DELETE SET NULL, requested_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), started_at TIMESTAMPTZ, completed_at TIMESTAMPTZ, error TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS scheduler_backups (id BIGSERIAL PRIMARY KEY, agent_id TEXT NOT NULL, job_id BIGINT REFERENCES scheduler_sync_jobs(id) ON DELETE SET NULL, captured_at TIMESTAMPTZ NOT NULL, device JSONB NOT NULL, users JSONB NOT NULL, attendance JSONB NOT NULL, uploaded_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS scheduler_jobs_agent_status_idx ON scheduler_sync_jobs (agent_id, status, requested_at);
CREATE INDEX IF NOT EXISTS scheduler_backups_agent_uploaded_idx ON scheduler_backups (agent_id, uploaded_at DESC);
